//! Grok Build鈥搒tyle harness mode (authority in Rust). //! //! Grok CLI keeps a **thin default tool surface**, escalates only when the //! task clearly needs ops/coding, attaches MCP by product match (never dumps //! every live schema), and gives chat enough turn budget (~15) without the //! old L0 max_iters=5 starvation trap. //! //! Python consults `harness_resolve` / `harness_select_mcp` RPCs; pure-Python //! mirrors exist only for offline unit tests.  use serde::{Deserialize, Serialize}; use serde_json::{json, Value};  /// Interactive thin (default) | shell/config ops | multi-file engineering. #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)] #[serde(rename_all = "snake_case")] pub enum HarnessMode {     Chat,     Ops,     Coding, }  impl HarnessMode {     pub fn as_str(self) -> &'static str {         match self {             Self::Chat => "chat",             Self::Ops => "ops",             Self::Coding => "coding",         }     }      pub fn parse(s: &str) -> Option<Self> {         match s.trim().to_ascii_lowercase().as_str() {             "chat" | "light" | "l0" | "l1" => Some(Self::Chat),             "ops" | "l2" => Some(Self::Ops),             "coding" | "code" | "l3" | "engineering" => Some(Self::Coding),             _ => None,         }     } }  /// Turn limits aligned with Grok headless / interactive feel. #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)] pub struct HarnessLimits {     pub max_iters: u32,     pub history_cap: u32,     pub tool_profile: &'static str,     pub ban_crew: bool,     pub ban_use_tool_pack: bool, }  impl HarnessMode {     pub fn limits(self) -> HarnessLimits {         match self {             // Grok-style thin: hard turn caps (not 40-round loops, not L0@5 either)             Self::Chat => HarnessLimits {                 max_iters: 8,                 history_cap: 40,                 tool_profile: "core",                 ban_crew: true,                 ban_use_tool_pack: true,             },             Self::Ops => HarnessLimits {                 max_iters: 12,                 history_cap: 48,                 tool_profile: "ops",                 ban_crew: true,                 ban_use_tool_pack: false,             },             Self::Coding => HarnessLimits {                 max_iters: 20,                 history_cap: 64,                 tool_profile: "coding",                 ban_crew: false,                 ban_use_tool_pack: false,             },         }     } }  /// Compatible L0鈥揕3 labels used by existing Python loop paths. #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)] pub enum LoopIntent {     L0,     L1,     L2,     L3, }  impl LoopIntent {     pub fn as_str(self) -> &'static str {         match self {             Self::L0 => "L0",             Self::L1 => "L1",             Self::L2 => "L2",             Self::L3 => "L3",         }     } }  fn contains_ci(hay: &str, needle: &str) -> bool {     if needle.is_empty() {         return false;     }     hay.to_ascii_lowercase()         .contains(&needle.to_ascii_lowercase()) }  fn contains_any_ci(hay: &str, needles: &[&str]) -> bool {     needles.iter().any(|n| contains_ci(hay, n)) }  fn is_team_dispatch(text: &str) -> bool {     contains_any_ci(         text,         &[             "娲剧粰",             "娲惧伐",             "鎸囨淳",             "浜ょ粰鍛樺伐",             "浜ょ粰宸ョ▼甯?,             "浜ょ粰鐮旂┒鍛?,             "璁╁憳宸?,             "璁╁伐绋嬪笀",             "瀹夋帓宸ョ▼甯?,             "鎷涜仒",             "椤圭洰缁?,             "鍙汉",             "澶氳鑹?,             "crew_steward",             "delegate",             "hire",             "assign",             "鍛樺伐鍘诲仛",             "鍚屼簨鍘诲仛",             "骞惰澶勭悊",             "骞惰璋冪爺",             "骞惰寮€鍙?,             "鎻愭潈",             "grant_caps",             "pending_grants",             "鍛樺伐鍒楄〃",             "缂栧埗鍒楄〃",             "requeue",         ],     ) }  /// Explicit write/create only 鈥?must NOT match "write a summary" / "fix the wording". /// Mirrors Python `write_intent.is_write_intent` (tight verbs, review veto). pub fn is_write_intent(text: &str) -> bool {     let t = text.trim();     if t.is_empty() {         return false;     }     let has_write = contains_any_ci(         t,         &[             "鍐欏叆",             "鍐欐枃浠?,             "鍐欎竴浠?,             "鍐欎笂",             "钀界洏",             "淇濆瓨鍒?,             "淇濆瓨涓?,             "淇濆瓨鎴?,             "file_write",             "apply_patch",             "閲嶆柊鍐?,             "鍐欏嚭鏉?,             "鍐欏ソ",             "琛ュ叏婧愮爜",             "琛ュ叏浠ｇ爜",             "琛ュ叏 crate",             "鏀逛唬鐮?,             "閲嶆瀯",             "瀹炵幇鍔熻兘",             "寮€鍙戜竴涓?,             "鍐欎竴涓」鐩?,             "鍐欎竴浠介」鐩?,             "淇bug",             "淇?bug",             "淇産ug",             "refactor",             "implement feature",             "create a pr",             "create pr",             "璧疯崏",             "浜у嚭鏂囨。",             "鍐?spec",             "鍐檚pec",             "鍐?PRD",             "鍐檖rd",         ],     );     if !has_write {         return false;     }     // Review-only language without a write verb 鈫?not write intent     let review = contains_any_ci(         t,         &[             "閫氳",             "瀹￠槄",             "鐪嬬湅",             "鐪嬩竴涓?,             "鐪嬩笅",             "鏈変粈涔堥棶棰?,             "妫€鏌ヤ竴涓?,             "璇讳竴涓?,             "review",             "甯垜鐪?,         ],     );     let write_verb = contains_any_ci(         t,         &[             "鍐欏叆",             "鍐欐枃浠?,             "鍐欎竴浠?,             "钀界洏",             "淇濆瓨",             "鐢熸垚",             "浜у嚭",             "璧疯崏",             "file_write",             "閲嶆柊鍐?,             "鍐欏嚭鏉?,             "鍐欏ソ",             "琛ュ叏",             "鏀逛唬鐮?,             "閲嶆瀯",         ],     );     if review && !write_verb {         return false;     }     true }  fn is_write_like(text: &str) -> bool {     is_write_intent(text) }  fn is_coding_like(text: &str) -> bool {     if is_write_like(text) {         return true;     }     // Heavy engineering / review 鈥?align with Python _HEAVY + review paths     if contains_any_ci(         text,         &[             "浠ｇ爜瀹℃煡",             "code review",             "review this",             "review the",             "review pr",             "review pull",             "瀹¤浠ｇ爜",             "鍏ㄤ粨",             "缂栬瘧澶辫触",             "pytest",             "cargo ",             "澶氭枃浠?,             "鐧诲綍椤?,             "pull request",             "github.com/",             "瀹¤",             "涓婄嚎",             "閮ㄧ讲",             // Python _HEAVY parity (path optimize / security / workforce topics)             "浼樺寲",             "鎬ц兘",             "鏉冮檺",             "瀹夊叏",             "宸ュ崟",             "缂栧埗",             "鍛樺伐杩涘害",             "鏀逛唬鐮?,             "瀹炵幇鍔熻兘",         ],     ) {         return true;     }     if contains_ci(text, "github")         && contains_any_ci(             text,             &["瀹?, "review", "pr", "pull", "issue", "commit", "浠撳簱", "repo"],         )     {         return true;     }     false }  /// True when text has real ops shell/proxy signals (full set for L1 demotion). fn has_ops_shell_signal(text: &str) -> bool {     contains_any_ci(         text,         &[             "proxy",             "tunnel",             "codex",             "powershell",             "http_proxy",             "https_proxy",             "浠ｇ悊",             "闅ч亾",             "3128",             "1080",             "鐜鍙橀噺",             "鍚姩 codex",             "鍚姩codex",             "杩炰笉閫?,             "宕╂簝",             "鍗歌浇鏈嶅姟",             "杩涚▼",             "绔彛",         ],     ) }  fn is_mcp_configure(text: &str) -> bool {     if text.is_empty() {         return false;     }     if contains_ci(text, "manage_mcp") {         return true;     }     let has_mcpish = contains_any_ci(         text,         &[             "mcp",             "api key",             "api_key",             "瀵嗛挜",             "tavily",             "firecrawl",             "璞嗗寘",             "doubao",         ],     );     if !has_mcpish {         return false;     }     // Avoid bare "瑁? (瑁呯/瑁呴グ) false positive 鈥?require configure-ish phrases     contains_any_ci(         text,         &[             "閰嶇疆",             "閰嶄竴涓?,             "閰嶄笅",             "閰嶅ソ",             "瀹夎",             "reload",             "鐑悓姝?,             "鍐欏瘑閽?,             "鏇存柊瀵嗛挜",             "缁欎綘鍔犱簡",             "env=",             "env =",             "瑁?mcp",             "瑁卪cp",             "瑁?璞嗗寘",             "瑁呰眴鍖?,             "瑁?tavily",             "瑁卼avily",             "瀹夎mcp",             "瀹夎 mcp",         ],     ) }  fn is_mcp_use(text: &str) -> bool {     if text.is_empty() || is_mcp_configure(text) {         return false;     }     contains_any_ci(         text,         &[             "鐢?tavily",             "鐢╰avily",             "鐢?璞嗗寘",             "鐢ㄨ眴鍖?,             "鐢?firecrawl",             "鐢╢irecrawl",             "鐢?mcp",             "鐢╩cp",             "via tavily",             "via mcp",             "mcp_tavily",             "mcp_web_search",             "mcp_fetch",             "mcp_firecrawl",             "璋冪敤 tavily",             "璋冪敤璞嗗寘",             "璧?tavily",             "tavily 鎼?,             "tavily鎼?,             "璞嗗寘鎼?,             "firecrawl 鎼?,         ],     ) }  fn is_ops_like(text: &str) -> bool {     if is_mcp_configure(text) {         return true;     }     has_ops_shell_signal(text) }  /// Built-in product tokens (Chinese aliases etc.). Custom servers also match /// via tokens that appear in live tool names (see `select_live_mcp_tools`). pub fn mcp_product_keywords(user_input: &str) -> Vec<&'static str> {     let t = user_input.to_ascii_lowercase();     let raw = user_input;     let mut hits: Vec<&'static str> = Vec::new();     let products: &[(&str, &[&str])] = &[         ("tavily", &["tavily"]),         ("firecrawl", &["firecrawl"]),         ("fetch", &["fetch"]),         ("github", &["github", "gh_"]),         ("doubao", &["doubao", "璞嗗寘", "askecho"]),     ];     for (canon, aliases) in products {         for a in *aliases {             if t.contains(&a.to_ascii_lowercase()) || raw.contains(a) {                 hits.push(*canon);                 break;             }         }     }     hits }  fn is_mcp_token_stop(tok: &str) -> bool {     matches!(         tok,         "the"             | "and"             | "for"             | "with"             | "from"             | "this"             | "that"             | "use"             | "using"             | "via"             | "call"             | "mcp"             | "api"             | "key"             | "token"             | "search"             | "list"             | "get"             | "set"             | "add"             | "http"             | "https"             | "www"             | "com"             | "tool"             | "tools"             | "server"             | "query"             | "please"             | "help"     ) }  /// Extract identifier-like tokens from user text for dynamic MCP matching. fn user_mcp_tokens(user_input: &str) -> Vec<String> {     let mut out: Vec<String> = Vec::new();     let mut cur = String::new();     for ch in user_input.chars() {         if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {             cur.push(ch.to_ascii_lowercase());         } else if !cur.is_empty() {             if cur.len() >= 2 && !is_mcp_token_stop(&cur) {                 out.push(cur.clone());             }             cur.clear();         }     }     if cur.len() >= 2 && !is_mcp_token_stop(&cur) {         out.push(cur);     }     out }  /// Grok-style matching-only attach. /// - Built-in product aliases (tavily/璞嗗寘/鈥? /// - **Any** live tool whose name contains a user-mentioned token (custom MCP) /// Empty keywords / no match 鈫?empty list (never dump 50鈥?0 schemas). pub fn select_live_mcp_tools(     user_input: &str,     live_names: &[String],     matching_only: bool,     auto_attach_all: bool, ) -> Vec<String> {     if live_names.is_empty() {         return vec![];     }     if auto_attach_all || !matching_only {         return live_names.to_vec();     }     // Configure intents: Python strips via is_mcp_configure; here keep product-only empty safe     let mut kws: Vec<String> = mcp_product_keywords(user_input)         .into_iter()         .map(|s| s.to_ascii_lowercase())         .collect();     // Dynamic: user tokens that appear in any live tool name     for tok in user_mcp_tokens(user_input) {         let hit = live_names.iter().any(|n| {             let nl = n.to_ascii_lowercase().replace('-', "_");             let t = tok.replace('-', "_");             nl.contains(&t)         });         if hit {             kws.push(tok);         }     }     if kws.is_empty() {         return vec![];     }     let mut out = Vec::new();     for name in live_names {         let nl = name.to_ascii_lowercase().replace('-', "_");         if kws.iter().any(|k| nl.contains(&k.replace('-', "_"))) {             out.push(name.clone());         }     }     out }  /// Default thin, escalate only (Grok/Claude/Codex product feel). pub fn resolve_harness_mode(     text: &str,     workforce: bool,     mode: Option<&str>,     write_intent: Option<bool>, ) -> HarnessMode {     let mode_l = mode.unwrap_or("").trim().to_ascii_lowercase();     if workforce || matches!(mode_l.as_str(), "cluster" | "goal" | "crew") {         return HarnessMode::Coding;     }     let t = text.trim();     if t.is_empty() {         return HarnessMode::Chat;     }     if t.starts_with("銆愮郴缁熉?) || t.starts_with("銆愬伐浣滀换鍔°€?) {         return HarnessMode::Coding;     }     if is_team_dispatch(t) {         return HarnessMode::Coding;     }     // Prefer explicit bridge flag; fall back to tight write detector (not "write a鈥?)     let write = write_intent.unwrap_or_else(|| is_write_intent(t));     if write || is_coding_like(t) {         return HarnessMode::Coding;     }     if is_ops_like(t) {         return HarnessMode::Ops;     }     HarnessMode::Chat }  pub fn classify_loop_intent(     text: &str,     workforce: bool,     mode: Option<&str>,     write_intent: Option<bool>, ) -> LoopIntent {     let h = resolve_harness_mode(text, workforce, mode, write_intent);     match h {         HarnessMode::Coding => LoopIntent::L3,         HarnessMode::Ops => {             // Pure MCP configure stays L1; any real shell/proxy signal 鈫?L2             if is_mcp_configure(text) && !has_ops_shell_signal(text) {                 LoopIntent::L1             } else {                 LoopIntent::L2             }         }         HarnessMode::Chat => {             if is_mcp_configure(text) {                 LoopIntent::L1             } else {                 LoopIntent::L0             }         }     } }  // 鈹€鈹€ Simple session (no crew dispatch) 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€  pub const DISPATCH_TOOL_NAMES: &[&str] = &[     "crew_steward",     "delegate_task",     "agent_call",     "manage_sub_agent", ];  fn is_crew_topic(text: &str) -> bool {     if contains_any_ci(         text,         &[             "缂栧埗",             "宸ュ崟",             "鎻愭潈",             "娲惧伐",             "鏀朵欢绠?,             "inbox",             "绠″",             "ceo",             "grant",             "棰勭畻",             "韬唤妗ｆ",             "capabilities",             "浠ょ墝",             "鍛樺伐鍒楄〃",             "鍛樺伐杩涘害",             "鍛樺伐缂栧埗",             "鍛樺伐妗ｆ",             "鍛樺伐鎻愭潈",             "鍛樺伐宸ュ崟",         ],     ) {         return true;     }     // (鏌鐪媩闂?鈥﹀伐绋嬪笀/鍛樺伐 鈥?do not treat as casual FAQ     if contains_any_ci(text, &["鏌?, "鐪?, "闂?])         && contains_any_ci(             text,             &["宸ョ▼甯?, "鐮旂┒鍛?, "鏂囩", "杩愮淮", "鍚屼簨", "鍛樺伐", "鐮佸啘", "寮€鍙?],         )         && !contains_any_ci(text, &["椋熷爞", "绂忓埄", "瀹胯垗"])     {         return true;     }     // role status probes     contains_any_ci(text, &["宸ョ▼甯?, "鐮旂┒鍛?, "鏂囩", "杩愮淮", "鍚屼簨", "鐮佸啘", "寮€鍙?])         && contains_any_ci(             text,             &["杩涘害", "鐘舵€?, "鍦ㄥ共鍢?, "鍦ㄥ仛浠€涔?, "蹇欎粈涔?, "鎬庝箞鏍?, "蹇欎笉蹇?],         ) }  fn is_ack_only(text: &str) -> bool {     let t = text.trim();     let low = t.to_ascii_lowercase();     matches!(         low.as_str(),         "濂? | "濂界殑" | "鍡? | "鍝? | "璋㈣阿" | "鎰熻阿" | "鏀跺埌"             | "ok" | "okay" | "thanks" | "thx" | "缁х画" | "涓嬩竴涓?             | "濂?" | "濂界殑!" | "ok!" | "thanks!"     ) || {         // strip trailing punct         let stripped: String = t             .chars()             .filter(|c| !matches!(c, '!' | '锛? | '銆? | '.' | '~' | '锝? | ' '))             .collect();         matches!(             stripped.to_ascii_lowercase().as_str(),             "濂? | "濂界殑" | "鍡? | "鍝? | "璋㈣阿" | "鎰熻阿" | "鏀跺埌"                 | "ok" | "okay" | "thanks" | "thx" | "缁х画" | "涓嬩竴涓?         )     } }  fn is_simple_pattern(text: &str) -> bool {     // Prefer high-confidence casual tokens; avoid bare "鏌ヤ竴涓?鐪嬬湅" (steward probes)     if contains_any_ci(         text,         &[             "澶╂皵",             "姘旀俯",             "涓嬮洦",             "weather",             "鐑悳",             "鐑偣",             "鐑棬椤圭洰",             "鐑棬寮€婧?,             "鐑棬浠撳簱",             "trending",             "寮€婧愰」鐩?,             "鐜板湪鍑犵偣",             "鍑犵偣浜?,             "what time",             "缈昏瘧",             "translate",             "浠€涔堟槸",             "what is",             "who is",             "鏄皝",             "鏂伴椈",             "鑲′环",             "姹囩巼",             "绠椾竴涓?,             "绠椾笅",             "鎬庝箞蹇?,             "鍚箟鏄粈涔?,             "define",         ],     ) {         return true;     }     // Short search-ish only when utterance is short (鈮?Python anchored patterns)     let n = text.chars().count();     n <= 60         && (text.starts_with("鎼滀竴涓?)             || text.starts_with("鏌ヤ竴涓?)             || text.starts_with("鐪嬬湅")             || text.starts_with("甯垜鎼?)             || text.starts_with("甯垜鏌?)             || text.starts_with("甯垜鐪嬬湅")             || text.starts_with("瑙ｉ噴涓€涓?)) }  fn is_multi_step(text: &str) -> bool {     if text.chars().count() <= 40 {         return false;     }     contains_any_ci(         text,         &[             "骞朵笖",             "鐒跺悗",             "鍚屾椂",             "鍒嗗埆",             "绗竴姝?,             "绗簩姝?,             "and then",             "step 1",             "step1",         ],     ) || (contains_ci(text, "鍏?) && contains_ci(text, "鍐?)) }  /// True when turn should stay in-session (strip crew dispatch tools). pub fn is_simple_session_intent(text: &str, max_chars: usize) -> bool {     let t = text.trim();     if t.is_empty() {         return false;     }     if t.starts_with("銆愮郴缁熉?) || t.starts_with("銆愬伐浣滀换鍔°€?) {         return false;     }     if is_team_dispatch(t) {         return false;     }     if is_coding_like(t) || is_write_intent(t) {         return false;     }     if is_crew_topic(t) {         return false;     }     if is_multi_step(t) {         return false;     }     if is_ack_only(t) {         return true;     }     if is_simple_pattern(t) {         let lim = max_chars.max(160);         return t.chars().count() <= lim;     }     false }  pub fn is_dispatch_tool_name(name: &str) -> bool {     let n = name.trim();     DISPATCH_TOOL_NAMES.iter().any(|d| *d == n) }  /// Filter tool names for simple session (strip dispatch). pub fn filter_dispatch_tool_names(names: &[String], strip: bool) -> Vec<String> {     if !strip {         return names.to_vec();     }     names         .iter()         .filter(|n| !is_dispatch_tool_name(n))         .cloned()         .collect() }  pub fn simple_session_from_value(params: &Value) -> Value {     let text = params         .get("text")         .or_else(|| params.get("user_input"))         .and_then(|v| v.as_str())         .unwrap_or("");     let max_chars = params         .get("max_chars")         .and_then(|v| v.as_u64())         .unwrap_or(200) as usize;     let force = params.get("force").and_then(|v| v.as_bool());     let simple = force.unwrap_or_else(|| is_simple_session_intent(text, max_chars));     let names: Vec<String> = params         .get("tool_names")         .or_else(|| params.get("tools"))         .and_then(|v| v.as_array())         .map(|a| {             a.iter()                 .filter_map(|x| x.as_str().map(|s| s.to_string()))                 .collect()         })         .unwrap_or_default();     let filtered = filter_dispatch_tool_names(&names, simple);     json!({         "simple_session": simple,         "strip_dispatch": simple,         "tool_names": filtered,         "dispatch_tools": DISPATCH_TOOL_NAMES,         "authority": "rust",     }) }  /// Full resolve payload for RPC / Python bridge. pub fn resolve_from_value(params: &Value) -> Value {     let text = params         .get("text")         .or_else(|| params.get("user_input"))         .and_then(|v| v.as_str())         .unwrap_or("");     let workforce = params         .get("workforce")         .and_then(|v| v.as_bool())         .unwrap_or(false);     let mode = params         .get("mode")         .and_then(|v| v.as_str());     let write_intent = params.get("write_intent").and_then(|v| v.as_bool());     let h = resolve_harness_mode(text, workforce, mode, write_intent);     let intent = classify_loop_intent(text, workforce, mode, write_intent);     // (names already positional)     let lim = h.limits();     // MCP-configure on ops/chat: use assistant profile so manage_mcp is available     let tool_profile = if intent == LoopIntent::L1 {         "assistant"     } else {         lim.tool_profile     };     let max_iters = if intent == LoopIntent::L1 {         10     } else {         lim.max_iters     };     let kws: Vec<String> = mcp_product_keywords(text)         .into_iter()         .map(|s| s.to_string())         .collect();     let light = matches!(h, HarnessMode::Chat) || intent == LoopIntent::L1;     let ops = h == HarnessMode::Ops && intent != LoopIntent::L1;     // Thrash thresholds for Python tool_round (authority hint)     // Grok: family thrash always on; tighter for chat     let cmd_family_force_after: u32 = if light {         3     } else if ops {         6     } else {         8 // coding: family thrash still on (was 0 鈫?46脳command empty loop)     };     // role_kind tip for loop_guard (final authority: loop_guard_resolve_role)     let role_kind = if workforce {         "implement"     } else if light || ops {         "chat"     } else {         "coding"     };     // Intent-only (do NOT OR light 鈥?L1 configure must not force strip_dispatch tip)     let simple = is_simple_session_intent(text, 200);     json!({         "harness_mode": h.as_str(),         "loop_intent": intent.as_str(),         "max_iters": max_iters,         "history_cap": lim.history_cap,         "tool_profile": tool_profile,         "light_loop": light,         "ops_loop": ops,         "ban_crew": lim.ban_crew || intent == LoopIntent::L1 || simple,         "ban_use_tool_pack": lim.ban_use_tool_pack && intent != LoopIntent::L1,         "mcp_configure": is_mcp_configure(text),         "mcp_use": is_mcp_use(text),         "mcp_keywords": kws,         "write_intent": is_write_intent(text),         "cmd_family_force_after": cmd_family_force_after,         "role_kind": role_kind,         "auto_continue": !(light || ops),         "max_segments": if light || ops { 1 } else { 5 },         "simple_session": simple,         "strip_dispatch": simple,         "dispatch_tools": DISPATCH_TOOL_NAMES,         "authority": "rust",     }) }  pub fn select_mcp_from_value(params: &Value) -> Value {     let text = params         .get("text")         .or_else(|| params.get("user_input"))         .and_then(|v| v.as_str())         .unwrap_or("");     let live: Vec<String> = params         .get("live_tools")         .or_else(|| params.get("tools"))         .and_then(|v| v.as_array())         .map(|a| {             a.iter()                 .filter_map(|x| x.as_str().map(|s| s.to_string()))                 .collect()         })         .unwrap_or_default();     let matching_only = params         .get("matching_only")         .and_then(|v| v.as_bool())         .unwrap_or(true);     let auto_attach = params         .get("auto_attach_all")         .or_else(|| params.get("auto_attach"))         .and_then(|v| v.as_bool())         .unwrap_or(false);     // Configure: never dump live schemas (Grok: manage path 鈮?tool dump)     if is_mcp_configure(text) && !auto_attach {         return json!({             "tools": [],             "keywords": mcp_product_keywords(text),             "reason": "mcp_configure_no_live_dump",             "authority": "rust",         });     }     let selected = select_live_mcp_tools(text, &live, matching_only, auto_attach);     json!({         "tools": selected,         "keywords": mcp_product_keywords(text),         "live_count": live.len(),         "selected_count": selected.len(),         "authority": "rust",     }) }  #[cfg(test)] mod tests {     use super::*;      #[test]     fn chat_default_for_path_faq() {         let h = resolve_harness_mode("鍛婅瘔鎴戜綘鍦ㄦ湰鏈虹殑鎵€鏈夎繍琛岃矾寰?, false, None, None);         assert_eq!(h, HarnessMode::Chat);         assert_eq!(h.limits().max_iters, 8);     }      #[test]     fn coding_for_github_review() {         let h = resolve_harness_mode(             "甯垜 review 杩欎釜 GitHub PR https://github.com/x/y/pull/1",             false,             None,             None,         );         assert_eq!(h, HarnessMode::Coding);         assert_eq!(classify_loop_intent(             "甯垜 review 杩欎釜 GitHub PR",             false,             None,             None,         ), LoopIntent::L3);     }      #[test]     fn ops_for_proxy_tunnel() {         let h = resolve_harness_mode("甯垜鐢ㄤ唬鐞?tunnel 鍚姩 codex", false, None, None);         assert_eq!(h, HarnessMode::Ops);     }      #[test]     fn mcp_configure_l1() {         assert_eq!(             classify_loop_intent(                 "鎴戠粰浣犲姞浜嗚眴鍖呮悳绱CP锛屼綘閰嶄笅api key",                 false,                 None,                 None,             ),             LoopIntent::L1         );     }      #[test]     fn mcp_use_matching_only() {         let live = vec![             "mcp_tavily_search".into(),             "mcp_firecrawl_scrape".into(),             "mcp_github_list".into(),         ];         let sel = select_live_mcp_tools("鐢?tavily 鎼?AI 鏂伴椈", &live, true, false);         assert_eq!(sel, vec!["mcp_tavily_search".to_string()]);         let none = select_live_mcp_tools("闅忎究鑱婅亰", &live, true, false);         assert!(none.is_empty());     }      #[test]     fn mcp_use_matching_custom_token_in_tool_name() {         let live = vec![             "mcp_my_crm_query".into(),             "mcp_tavily_search".into(),         ];         let sel = select_live_mcp_tools("鐢?my-crm 鏌ュ鎴?, &live, true, false);         assert_eq!(sel, vec!["mcp_my_crm_query".to_string()]);     }      #[test]     fn configure_does_not_dump_live() {         let live: Vec<String> = vec!["mcp_tavily_search".into(), "mcp_x".into()];         let v = select_mcp_from_value(&json!({             "text": "閰嶄笅 tavily 鐨?api key",             "live_tools": live,             "matching_only": true,         }));         assert_eq!(v["tools"].as_array().unwrap().len(), 0);     }      #[test]     fn workforce_always_coding() {         assert_eq!(             resolve_harness_mode("鐪嬩笅澶╂皵", true, None, None),             HarnessMode::Coding         );     }      #[test]     fn no_english_write_a_false_positive() {         assert_eq!(             resolve_harness_mode("write a short summary of the meeting", false, None, Some(false)),             HarnessMode::Chat         );         assert_eq!(             resolve_harness_mode("fix the wording of this email", false, None, Some(false)),             HarnessMode::Chat         );     }      #[test]     fn heavy_optimize_is_coding() {         assert_eq!(             resolve_harness_mode("甯垜鐪嬬湅鎵ц璺緞鎬庝箞浼樺寲", false, None, None),             HarnessMode::Coding         );     }      #[test]     fn configure_plus_env_is_l2_ops() {         assert_eq!(             classify_loop_intent("閰嶄竴涓?MCP 鐜鍙橀噺", false, None, None),             LoopIntent::L2         );     }      #[test]     fn bare_zhuang_not_configure() {         assert!(!is_mcp_configure("璞嗗寘瑁呯鍦板潃鏄粈涔?));     }      #[test]     fn simple_session_weather_and_strip() {         assert!(is_simple_session_intent("浠婂ぉ澶╂皵鎬庝箞鏍?, 200));         assert!(!is_simple_session_intent("娲剧粰宸ョ▼甯堝仛浠ｇ爜瀹℃煡", 200));         assert!(!is_simple_session_intent("鏌ヤ竴涓嬪伐绋嬪笀", 200));         let names = vec![             "web_search".into(),             "crew_steward".into(),             "file_read".into(),         ];         let f = filter_dispatch_tool_names(&names, true);         assert_eq!(f, vec!["web_search".to_string(), "file_read".to_string()]);     } }